prog='''def comps(g, color):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]==color and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<R and 0<=b<C and g[a][b]==color and (a,b) not in seen:
                                seen.add((a,b)); st.append((a,b))
                out.append(c)
    return out

def transform(g, th=4):
    from collections import Counter
    R,C=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[[bg]*C for _ in range(R)]
    for col in set(x for r in g for x in r)-{bg}:
        for c in comps(g,col):
            if len(c)>=th:
                ys=[p[0] for p in c]; xs=[p[1] for p in c]
                for i in range(min(ys),max(ys)+1):
                    for j in range(min(xs),max(xs)+1):
                        out[i][j]=col
    return out
'''
